module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

    reg [1:0] cnt;
    reg [9:0] tmp_data;

    wire [9:0] tmp_data_next;
    assign tmp_data_next = tmp_data + data_in;

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            tmp_data <= 10'd0;
            cnt <= 2'd0;
            valid_out <= 1'd0;
        end
        else begin
            case(cnt)
                2'd0: begin
                    if(valid_in) begin
                        tmp_data <= data_in;
                        cnt <= cnt + 2'd1;
                    end
                    else begin
                        tmp_data <= tmp_data;
                        cnt <= cnt;
                    end
                end

                2'd1: begin
                    if(valid_in) begin
                        tmp_data <= tmp_data_next;
                        cnt <= cnt + 2'd1;
                    end
                    else begin
                        tmp_data <= tmp_data;
                        cnt <= cnt;
                    end
                end

                2'd2: begin
                    if(valid_in) begin
                        tmp_data <= tmp_data_next;
                        cnt <= cnt + 2'd1;
                    end
                    else begin
                        tmp_data <= tmp_data;
                        cnt <= cnt;
                    end
                end

                2'd3: begin
                    if(valid_in) begin
                        tmp_data <= tmp_data_next;
                        cnt <= cnt + 2'd1;
                    end
                    else begin
                        tmp_data <= tmp_data;
                        cnt <= cnt;
                    end
                end

                default: begin
                    tmp_data <= 10'd0;
                    cnt <= 2'd0;
                end

            endcase

            if(cnt == 2'd3) begin
                valid_out <= 1'd1;
            end
            else begin
                valid_out <= 1'd0;
            end
        end
    end

    always@(*) begin
        data_out = tmp_data;
    end

endmodule
